(1,'c14f9e90-bcdb-419b-abf4-e3a3002d6283',10,1,'Waterproofing up-stand height','Spec says 300 mm up-stand; shower area requires 1800 mm? Confirm.','Sandeep Yadav','2026-09-18 12:00:00','NORMAL',1,'ANSWERED','1800 mm in shower zone, 300 mm elsewhere.','Ritika Sharma','2026-09-20 15:00:00',NULL,'["/uploads/demo/rfi/1-1.jpg"]','2026-09-18 12:00:00','2026-09-20 15:00:00'),
(2,'c14f9e90-bcdb-419b-abf4-e3a3002d6283',11,2,'Cove light profile size','Approved profile 2 m not available; 3 m available ex-stock. OK to substitute?','Sandeep Yadav','2026-09-05 12:00:00','LOW',5,'CLOSED','OK to use 3 m, cut to size.','Ritika Sharma','2026-09-07 15:00:00','2026-09-10 11:00:00','["/uploads/demo/rfi/1-2.jpg"]','2026-09-05 12:00:00','2026-09-10 15:00:00'),
