(4,'bbbe795e-3a69-4ba7-8918-da5647d100c3',11,1,'AC drain routing','No drain point near master bedroom indoor unit. Route through false ceiling to balcony?','Manoj Rawat','2026-09-11 12:00:00','HIGH',8,'ANSWERED','Yes, with 1:100 slope and insulated pipe.','Arjun Mehra','2026-09-13 15:00:00',NULL,'["/uploads/demo/rfi/2-1.jpg"]','2026-09-11 12:00:00','2026-09-13 15:00:00'),
